css:
* {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: Arial, sans-serif;
            font-size: 14px;
            color: #000;
            background: #f5f5f5;
        }

        .invoice-wrapper {
            border: 2px solid #000;
            padding: 8px;
            background: white;
            max-width: 210mm;
            margin: 0 auto;
        }

        .invoice-header {
            text-align: center;
            margin-bottom: 5px;
        }

        .main-title {
            font-size: 14px;
            font-weight: bold;
            text-transform: uppercase;
            margin: 0;
            letter-spacing: 1px;
        }

        .company-name {
            font-size: 16px;
            font-weight: bold;
            margin: 4px 0;
        }

        .company-address {
            font-size: 9px;
            margin: 1px 0;
            line-height: 1.3;
        }

        .info-table {
            width: 100%;
            border-collapse: collapse;
            margin: 3px 0;
            font-size: 9px;
            border: 1px solid #000;
        }

        .info-table td {
            border: 1px solid #000;
            padding: 4px 3px;
            vertical-align: top;
        }

        .text-right {
            text-align: right;
        }

        .text-center {
            text-align: center;
        }

        .three-column-table {
            width: 100%;
            border-collapse: collapse;
            margin: 5px 0;
            border: 1px solid #000;
        }

        .three-column-table td {
            vertical-align: top;
            padding: 5px;
            border: 1px solid #000;
        }

        .section-header {
            font-weight: bold;
            font-size: 9px;
            margin-bottom: 4px;
            padding-bottom: 2px;
            border-bottom: 1px solid #000;
        }

        .compact-section {
            font-size: 9px;
            line-height: 1.4;
        }

        /* Main items table - this includes header in thead */
        .items-table {
            width: 100%;
            border-collapse: collapse;
            font-size: 9px;
            border: 1px solid #000;
        }

        .items-table thead th {
            border: 1px solid #000;
            padding: 4px 3px;
            font-weight: bold;
            background: #eaeaea;
        }

        .items-table tbody td {
            border: 1px solid #000;
            padding: 4px 3px;
            vertical-align: top;
        }

        /* Header rows that will be part of thead */
        .header-row td {
            border: 1px solid #000;
            padding: 4px 3px;
            vertical-align: top;
            background: white;
        }

        .amount-box {
            margin: 5px 0;
            font-size: 9px;
            padding: 5px;
            border: 1px solid #000;
        }

        .amount-line {
            margin: 2px 0;
        }

        .terms {
            font-size: 8px;
            line-height: 1.3;
            margin: 5px 0;
            padding: 5px;
        }

        .footer {
            text-align: center;
            font-size: 8px;
            margin-top: 10px;
            padding-top: 5px;
            border-top: 1px dotted #000;
        }

        .item-description {
            font-size: 9px;
            line-height: 1.2;
        }

        .serial-number {
            font-size: 8px;
            color: #333;
        }

        .warranty-info {
            font-size: 8px;
            color: #555;
            font-style: italic;
        }

        .tax-table {
            width: 100%;
            border-collapse: collapse;
            font-size: 14px;
            border: 1px solid #000;
            margin: 5px 0;
        }

        .tax-table th,
        .tax-table td {
            border: 1px solid #000;
            padding: 4px;
        }

        .tax-table th {
            background: #eaeaea;
            font-weight: bold;
        }

        .tax-total-row {
            font-weight: bold;
            background: #f0f0f0;
        }

        /* Print styles */
        @media print {
            body {
                background: white;
                print-color-adjust: exact;
                -webkit-print-color-adjust: exact;
            }

            @page {
                margin: 15mm 10mm;
                size: A4;
            }

            .invoice-wrapper {
                border: none;
                padding: 0;
                max-width: 100%;
            }

            /* Make thead repeat on every page */
            .items-table thead {
                display: table-header-group;
            }

            .items-table tbody {
                display: table-row-group;
            }

            /* Prevent page breaks inside rows */
            .items-table tbody tr {
                page-break-inside: avoid;
                page-break-after: auto;
            }

            /* Keep footer together */
            .footer-section {
                page-break-inside: avoid;
            }

            .tax-table {
                page-break-inside: avoid;
            }
        }
        @media print {
    @page {
        size: A4;
        margin: 12mm;
    }

    .items-table {
        width: 100%;
        border-collapse: collapse;
    }

    .items-table thead {
        display: table-header-group;  
    }

    .items-table tbody {
        display: table-row-group;
    }

    .items-table tbody tr {
        page-break-inside: avoid;
    }

    .header-row td,
    .items-table th,
    .items-table td {
        border: 1px solid #000;
        padding: 4px;
        font-size: 14px;
    }

    .main-title {
        font-size: 14px;
        font-weight: bold;
        text-align: center;
    }

    .section-header {
        font-weight: bold;
        border-bottom: 1px solid #000;
        margin-bottom: 3px;
    }

}
